#include <cstdio>
#include <algorithm>
#include <cmath>
using namespace std;

typedef long long ll;
const ll N = 1000000007LL;

ll read()
{
    ll a = 0, b = 1;
    char c = getchar();
    while (c < '0' || c > '9')
    {
        if (c == '-') b = -1;
        c = getchar();
    }
    while (c >= '0' && c <= '9')
    {
        a = a * 10 + c - '0';
        c = getchar();
    }
    return a * b;
}

ll quickpow(ll m, ll n)
{
    if (n == 0) return 1;
    ll t = quickpow(m, n / 2) % N;
    if (n % 2 == 0)
        return t * t % N;
    return m % N * t % N * t % N;
}

ll n, m;

int main()
{
    n = read();
    m = read();
    n = n + 1;
    printf("%lld", (quickpow(2 * n, m) * (n - m) / n) % N);
    return 0;
}

